// SSE Stream parser for Cerebras API
struct StreamResponse {
    std::string fullText;
    std::vector<std::string> chunks;
};

size_t StreamCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    size_t realsize = size * nmemb;
    StreamResponse* response = static_cast<StreamResponse*>(userp);
    std::string data(static_cast<char*>(contents), realsize);

    // Parse SSE format: data: {"choices":[{"delta":{"content":"text"}...}]}
    std::istringstream stream(data);
    std::string line;

    while (std::getline(stream, line)) {
        if (line.substr(0, 6) == "data: ") {
            std::string jsonData = line.substr(6);

            // Extract content from JSON using regex
            std::regex contentRegex(R"("content":"([^"]*)")");
            std::smatch match;

            if (std::regex_search(jsonData, match, contentRegex)) {
                std::string content = match[1].str();
                if (!content.empty()) {
                    response->chunks.push_back(content);
                    response->fullText += content;
                    std::cout << content << std::flush;
                }
            }
        }
    }

    return realsize;
}

std::string sendToCerebras(const std::string& message) {
    CURL* curl;
    CURLcode res;
    StreamResponse response;

    const char* apiKey = std::getenv("CEREBRAS_API_KEY");
    if (!apiKey) {
        return "{\"error\":\"CEREBRAS_API_KEY not set\"}";
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
        std::string jsonPayload = "{"
